INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(120593, 'ruRU', '', 'Мы скоро встретимся снова.', 24330),
(120594, 'ruRU', '', 'Умри достойно.', 24330),
(120595, 'ruRU', '', 'Однажды я могу прийти за тобой.', 24330),
(120607, 'ruRU', '', 'Скажи мне, что ты не всерьёз рассматриваешь отправку нашего друга на такую миссию. Это самоубийство.', 24330),
(120608, 'ruRU', '', 'Я лично видел, что энергии Аркан''дора делают для Иссохших. Я верю, что это стоит риска.', 24330),
(120609, 'ruRU', '', 'Хмф. Тогда нам остаётся лишь ждать и смотреть.', 24330),
(120613, 'ruRU', '', 'Я действительно наслаждаюсь хорошей дракой.', 24330),
(120615, 'ruRU', '', 'Бесстрашен мой натиск, Верховный лорд! За Орден!', 24330),
(120616, 'ruRU', '', 'Свет направит мою руку, Верховный лорд.', 24330),
(120617, 'ruRU', '', 'Я тебя не разочарую, Верховный лорд.', 24330),
(120620, 'ruRU', '', 'Для меня честь присоединиться к тебе, Великий мастер. Мой учитель был бы горд.', 24330),
(120621, 'ruRU', '', 'У меня хорошее предчувствие насчёт тебя, друид. Твой дух горит ярко. Ты не поведёшь нас неверным путём.', 24330),
(120634, 'ruRU', '', 'Замаскированные громилы преследуют моих сторонников. Я знаю, что за этим стоят эти звери из Дома Стеллерис!', 24330),
(120635, 'ruRU', '', '<Вздыхает.> Политика как обычно. Возможно, после того как мы освободим Сурамар, мои противники поймут, что были на неправильной стороне истории.', 24330),
(120645, 'ruRU', '', 'Ты уже принял решение, $ct?$b$bЯ бы дал тебе совет, но в этом деле ты должен заглянуть внутрь себя.', 24330),
(120664, 'ruRU', '', 'Ну здравствуй, посетитель! Спасибо, что заглянул ко мне.', 24330),
(120665, 'ruRU', '', 'Я рассказывала тебе о своих внучках, Алексис, Келси и Каре? Такие смышлёные девочки!$B$BЯ не видела их с тех самых пор... <Пегги замолкает, затем умиротворённо улыбается.>$B$BЧто ж, я скучаю по ним и надеюсь, что у них всё хорошо.', 24330),
(120666, 'ruRU', '', 'Готов начать демонстрацию отжима сока?', 24330),
(120682, 'ruRU', '', 'Сирилла кладёт сумеречную лилию на тело надзирателя Дюрана.', 24330),
(120694, 'ruRU', '', 'Мурлоки Бухты Обломков были замечены за поклонением Морскому Гиганту по имени Обломок. Положи конец этому существу.', 24330),
(120695, 'ruRU', '', 'Обломку следовало оставаться скрытым в море. Благодарю, защитник, мой народ теперь в большей безопасности благодаря тебе.', 24330),
(120722, 'ruRU', '', 'Я здесь, чтобы препроводить достойных в Небесную Твердыню!', 24330),
(120729, 'ruRU', '', 'Я готов избавиться от этого голода и привести свой народ к спасению.', 24330),
(120730, 'ruRU', '', 'Я возьму то же, что и Окулет.', 24330),
(120734, 'ruRU', '', 'Изгнанные Ночнорождённые удерживаются Легионом в плену. Освободи их, прежде чем они встретят ужасную судьбу!', 24330),
(120735, 'ruRU', '', 'Я не уверен, что хуже — иссохнуть или превратиться в топливо для военных машин Легиона. Благодарю за то, что спас их.', 24330),
(120755, 'ruRU', '', 'Что ты делаешь? Что не так с твоим телом?', 24330),
(120756, 'ruRU', '', 'Почему ты двигаешься так странно?', 24330),
(120757, 'ruRU', '', 'Ба! Можешь танцевать, если хочешь. Но ты оставляешь своих друзей позади...', 24330),
(120758, 'ruRU', '', 'Я недостаточно повеселился, чтобы терпеть то, что ты делаешь.', 24330),
(120759, 'ruRU', '', 'Прекрати! Это глупо.', 24330),
(120760, 'ruRU', '', 'Мы, Ночнорождённые, обязаны своей несравненной изысканностью и интеллектом благородному наследию. Предки, покоящиеся в Тель''аноре, заслуживают должного почтения.', 24330),
(120761, 'ruRU', '', 'Ах, ты пришёл! И как раз вовремя к занятию по вычерчиванию рун.$b$bНапомни-ка мне, над какой руной ты работал?', 24330),
(120762, 'ruRU', '', 'Да, конечно, верно. И на каком уровне?', 24330),
(120763, 'ruRU', '', 'Хорошо, вот контур твоей руны. Удачи!', 24330),
(120790, 'ruRU', '', 'Добро пожаловать в Академию Нар''таласа. Прошу, чувствуй себя как дома. Здесь рады всем, кто готов учиться.', 24330),
(120791, 'ruRU', '', 'Многое. Ты можешь просмотреть наши стеллажи, попрактиковаться в бою против любого из наших тренировочных манекенов или просто провести время в общении с сокурсниками. Можешь даже привести друзей, если хочешь. Это безопасное место.$b$bКроме того, инструктор Нидриэль ведёт занятия по вычерчиванию рун, а наш научный ассистент Сайторн работает над исследованием боя с существами. Уверен, каждый из них будет рад поработать с тобой.', 24330),
(120792, 'ruRU', '', 'Не сейчас. Проведи немного больше времени, общаясь с другими инструкторами, и я могу это рассмотреть.', 24330),
(120793, 'ruRU', '', 'Дуэль? Если настаиваешь. Полагаю, немного боя никому не повредило. Хотя, вообще-то, это, вероятно, неточно.\nГотова, когда будешь готов ты!', 24330),
(120794, 'ruRU', '', 'Я сдаюсь. Победить свою директрису — это не пустяковый подвиг. Поздравляю.', 24330);
